mapper.select:
SELECT t2.CODE applyCode, t1.specimen_id specimenCode, t1.specimen_code microbeCode, t1.chinese_name chineseName, t1.latin_name latinName, stock_id stockId FROM strain_outbound_sub_application t1 LEFT JOIN strain_outbound_application t2 ON t2. id = t1.parent_id WHERE resave = 0 AND t2.appro_result = 2
AND t2.CODE = #{applyCode}
order by t2.code
